function bindQuantityControl(input,whole=false){
 let wrap=input.closest('.quantity-control');if(!wrap){wrap=document.createElement('div');wrap.className='quantity-control';input.before(wrap);wrap.append(input);const arrows=document.createElement('div');arrows.className='quantity-arrows';arrows.innerHTML='<button type="button" aria-label="Aumenta quantità">▲</button><button type="button" aria-label="Diminuisci quantità">▼</button>';wrap.append(arrows);const label=document.createElement('label');label.className='quantity-increment';label.textContent='Passo dei pulsanti +/−';const choice=document.createElement('select');choice.setAttribute('aria-label','Incremento della quantità');choice.innerHTML='<option value="1">Unità intere (+1)</option><option value="0.1">Decimali (+0,1)</option>';label.append(choice);wrap.after(label);wrap.incrementChoice=choice;const move=direction=>{if(input.disabled)return;const minimum=Number(input.min)||0,maximum=input.max?Number(input.max):Infinity,value=Number(input.value)||0,next=Math.round((value+direction*Number(choice.value))*10)/10;input.value=String(Math.max(minimum,Math.min(maximum,next)));input.dispatchEvent(new Event('input',{bubbles:true}));};arrows.children[0].onclick=()=>move(1);arrows.children[1].onclick=()=>move(-1);input.addEventListener('keydown',e=>{if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();move(e.key==='ArrowUp'?1:-1);}});}
 const choice=wrap.incrementChoice;choice.options[1].disabled=whole;choice.value=whole?'1':(wrap.wasWhole===false?choice.value:'0.1');wrap.wasWhole=whole;input.step=whole?'1':(Number(input.value)*10!==Math.round(Number(input.value)*10)?'any':'.1');
}
/* Saveat — browser client. Authorization and inventory live in PostgreSQL. */
'use strict';
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>Number(v)===0?'Gratis':new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR'}).format(Number(v));
const when=v=>new Intl.DateTimeFormat('it-IT',{dateStyle:'short',timeStyle:'short'}).format(new Date(v));
let db=null,session=null,profile=null,current=null,myTab='listings',page=0,itemSequence=0,routeGeneration=0;
let homeCity=null,homeAreaReady=false;
let searchCity=null,publishCity=null,pendingRequest=null,titleEdited=false,reservationFilter=null,mineGeneration=0,listingsSequence=0,notificationFingerprint=null;

const paymentLabels={cash:'Contanti',card:'Carta/POS',satispay:'Satispay'};
function paymentFields(prefix,selected=[]){return '<fieldset class="payment-options" id="'+prefix+'-payments"><legend>Metodi di pagamento accettati</legend>'+Object.entries(paymentLabels).map(([value,label])=>'<label class="container-check"><input type="checkbox" name="'+prefix+'-payment" value="'+value+'" '+(selected?.includes(value)?'checked':'')+'> '+label+'</label>').join('')+'<p class="small">Il pagamento avviene al punto di ritiro.</p></fieldset>';}
function selectedPayments(prefix){return [...document.querySelectorAll('input[name="'+prefix+'-payment"]:checked')].map(i=>i.value);}
function paymentSummary(methods,selling){if(!selling)return '';return '<p class="payment-summary"><b>Pagamenti accettati:</b> '+(methods?.length?methods.map(m=>esc(paymentLabels[m]||m)).join(', '):'Da concordare con chi vende')+' · al punto di ritiro.</p>';}
function descriptionBlock(text){return text?.trim()?'<div class="listing-description"><b>Descrizione</b><p>'+esc(text)+'</p></div>':'';}
function currentReservationInfo(item){const c=item.current_item;if(!c)return '';const changed=c.name!==item.name||c.unit!==item.unit;return (changed?'<p class="small"><b>Annuncio corretto:</b> '+esc(c.name)+' · '+esc(item.inventory_quantity??item.quantity)+' '+esc(c.unit)+'. I dati iniziali della prenotazione e il totale restano conservati.</p>':'')+(c.label_date?'<p class="small">'+(c.date_type==='use_by'?'Da consumare entro':'Da consumarsi preferibilmente entro')+': '+esc(c.label_date)+'</p>':'')+(c.allergens?'<p class="small">Informazioni in etichetta: '+esc(c.allergens)+'</p>':'')+(c.container_provided!==item.container_provided?'<p class="small"><b>Indicazione aggiornata:</b> '+esc(containerMessage(c))+'</p>':'');}
function editUnitChoice(fs){const item=editListing.saveat_items.find(i=>i.id===fs.dataset.editItem),unit=fs.querySelector('[data-edit-field="unit"]').value,changed=unit!==item.unit,conversion=fs.querySelector('[data-edit-field="unit_conversion"]'),committed=Number(fs.dataset.committed),needs=changed&&committed>0;fs.querySelector('.unit-conversion').hidden=!needs;conversion.required=needs;const factor=needs?Number(conversion.value)||0:1,qty=fs.querySelector('[data-edit-field="quantity"]');qty.min=Math.max(['pezzi','confezioni'].includes(unit)?1:.1,Math.ceil(committed*factor*10)/10);qty.step=['pezzi','confezioni'].includes(unit)?'1':'.1';bindQuantityControl(qty,['pezzi','confezioni'].includes(unit));updateContainerChoice(fs,true);}

function syncListingTitle(){if(!titleEdited)$('title').value=$('item-fields').querySelector('[data-field="name"]')?.value.trim()||'';}
function refreshItemLabels(){[...$('item-fields').children].forEach((fs,index)=>{fs.querySelector('legend').textContent=index===0?'Cosa vuoi condividere?':'Alimento '+(index+1);fs.querySelector('.remove-item').hidden=$('item-fields').children.length===1;});const count=$('item-fields').children.length;const summary=$('publish-item-count');if(summary)summary.textContent=count+(count===1?' alimento nell’annuncio':' alimenti nell’annuncio');syncListingTitle();}

// Un solo flusso, con memoria privata sincronizzata per account.
const surplusCategories=['Pane e prodotti da forno','Frutta e verdura','Pasticceria e dolci','Gastronomia e piatti pronti','Latticini e formaggi','Carne e salumi','Pesce','Prodotti confezionati','Bevande','Altri alimenti'];
const businessPickupContact='Ritiro tramite Saveat: segui le istruzioni e mostra la prenotazione al punto di ritiro.';
let foodMemory=[],foodMemoryAccount=null,foodMemorySequence=0;
function isSurplus(items){return items?.some(i=>surplusCategories.some(c=>i.name?.startsWith(c+' — ')));}
function surplusNotice(items){return isSurplus(items)?'<p class="ethic"><b>Controlla il contenuto.</b> Leggi specifiche, quantità, unità e allergeni. Se i dettagli non bastano per le tue esigenze, non prenotare. Chi pubblica deve concordare con te eventuali sostituzioni.</p>':'';}
function rowSelling(fs){return fs.querySelector('[data-field="offer"]').value==='sell';}
function prepareBusinessPublication(){const business=profile?.account_type==='business';$('contact').closest('.pickup-contact').hidden=business;$('contact').required=!business;$('business-contact-note').hidden=!business;if(business)$('contact').value=businessPickupContact;else if($('contact').value===businessPickupContact)$('contact').value='';}
function normalizedFood(food){const copy={...food};if(!copy.category){const category=surplusCategories.find(c=>copy.name?.startsWith(c+' — '));if(category){copy.category=category;copy.name=copy.name.slice(category.length+3);}}return copy;}
function foodKey(food){return (food.category||'').trim().toLocaleLowerCase('it')+'\n'+food.name.trim().toLocaleLowerCase('it');}
async function loadFoodMemory(){const uid=session?.user.id,sequence=++foodMemorySequence;foodMemory=[];foodMemoryAccount=uid;if(!uid)return;$('food-memory-status').textContent='Caricamento dei tuoi alimenti precedenti…';try{const rows=await rpc('saveat_food_suggestions');if(uid!==session?.user.id||sequence!==foodMemorySequence)return;const seen=new Set();foodMemory=(rows||[]).map(normalizedFood).filter(f=>{if(!f.name)return false;const key=foodKey(f);if(seen.has(key))return false;seen.add(key);return true;});$('food-memory-status').textContent=foodMemory.length?'Scrivi un nuovo alimento oppure scegli tra i tuoi precedenti. Solo tu puoi richiamare i tuoi alimenti precedenti.':'Inserisci il primo alimento. Dopo la pubblicazione potrai richiamarlo qui.';document.querySelectorAll('#item-fields .item-field').forEach(fs=>renderFoodSuggestions(fs));}catch(e){if(uid===session?.user.id&&sequence===foodMemorySequence)$('food-memory-status').textContent='Gli alimenti precedenti non sono disponibili. Puoi comunque inserirne uno nuovo.';}}
function renderFoodSuggestions(fs,showAll=false){const box=fs.querySelector('.food-suggestions'),input=fs.querySelector('[data-field="name"]'),query=input.value.trim().toLocaleLowerCase('it');box.replaceChildren();if(foodMemoryAccount!==session?.user.id)return;const matches=foodMemory.filter(f=>showAll||query&&[f.name,f.category].join(' ').toLocaleLowerCase('it').includes(query));if(!matches.length){box.hidden=true;return;}box.hidden=false;const status=document.createElement('p');status.className='small';status.textContent='I tuoi alimenti precedenti — scegli per compilare questa riga';box.append(status);for(const food of matches){const button=document.createElement('button');button.type='button';button.className='ghost food-suggestion';button.textContent=food.name+' · '+food.unit+' · '+money(food.price);button.onclick=()=>restoreFood(fs,food);box.append(button);}}
function restoreFood(fs,food){if(foodMemoryAccount!==session?.user.id)return;const get=k=>fs.querySelector('[data-field="'+k+'"]');get('name').value=food.name;get('category').value=food.category||'';get('food_description').value=food.description||'';get('unit').value=food.unit;get('offer').value=food.offer||(Number(food.price)>0?'sell':'donate');get('price').value=Number(food.price)>0?food.price:'';get('allergens').value=food.allergens||'';get('weight').value=food.unit_weight_kg?Number(food.unit_weight_kg)*1000:'';get('container').checked=food.container_provided===true;get('quantity').value='';get('date_type').value='none';get('label_date').value='';get('label_date').required=false;fs.querySelector('.photo-remove').click();fs.querySelector('.photo-status').textContent='Aggiungi una foto aggiornata, se utile.';adjustItemQuantity(fs);updateContainerChoice(fs);updateOfferMode();syncListingTitle();fs.querySelector('.food-suggestions').hidden=true;fs.querySelector('.memory-filled').hidden=false;fs.reusableDefaults=food.defaults||{};$('food-check').checked=false;get('quantity').focus();}
function restorePickupDefaults(fs){const d=fs.reusableDefaults;if(!d)return;if(d.municipality_code&&d.city_name){publishCity={code:d.municipality_code,name:d.city_name,province:d.province};$('publish-city').value=d.city_name+' ('+d.province+')';}for(const [id,key] of [['address','address'],['instructions','instructions'],['description','description']])$(id).value=d[key]||'';if(profile?.account_type!=='business')$('contact').value=d.contact||'';$('publish-payment-fields').innerHTML=paymentFields('publish',d.payment_methods||[]);prepareBusinessPublication();updateOfferMode();notice('Dati di ritiro richiamati. Controllali e inserisci la nuova fascia oraria.');}
function setupFoodRow(fs){const n=fs.dataset.sequence,name=fs.querySelector('[data-field="name"]');name.autocomplete='off';name.placeholder='Scrivi un nuovo alimento o cerca tra i tuoi';const box=document.createElement('div');box.innerHTML='<button type="button" class="ghost show-foods">Scegli un alimento già pubblicato</button><div class="food-suggestions" hidden></div><div class="memory-filled" hidden><p class="small">Dati dell’alimento precedente compilati. Puoi modificarli tutti. Inserisci la quantità attuale e controlla date, allergeni e conservazione.</p><button type="button" class="ghost restore-pickup">Riutilizza i dati di ritiro</button></div><label for="category-'+n+'">Categoria</label><select id="category-'+n+'" data-field="category"><option value="">Scegli una categoria (facoltativo)</option>'+surplusCategories.map(c=>'<option>'+esc(c)+'</option>').join('')+'</select><label for="food-description-'+n+'">Descrizione dell’alimento (facoltativa)</label><textarea id="food-description-'+n+'" data-field="food_description" maxlength="1000" placeholder="Es. pane integrale, confezione da circa 500 g"></textarea><label for="offer-'+n+'">Come vuoi condividere questo alimento?</label><select id="offer-'+n+'" data-field="offer"><option value="donate">Dona — gratis</option><option value="sell">Vendi — prezzo per unità</option></select>';name.after(box);box.querySelector('.show-foods').onclick=()=>renderFoodSuggestions(fs,true);box.querySelector('.restore-pickup').onclick=()=>restorePickupDefaults(fs);name.oninput=()=>{syncListingTitle();renderFoodSuggestions(fs);};name.onkeydown=e=>{if(e.key==='Escape')box.querySelector('.food-suggestions').hidden=true;};box.querySelector('[data-field="offer"]').onchange=updateOfferMode;}
const guidanceOptions={customer:{pickup_location:'Non trovo il punto di ritiro',food_information:'Chiarimenti su contenuto / allergeni',running_late:'Arrivo in ritardo'},owner:{instructions_updated:'Ho verificato le indicazioni di ritiro',pickup_confirmed:'Confermo la fascia di ritiro',pickup_deadline:'Il ritiro è possibile solo entro l’orario indicato'}};
function guidanceBlock(r,owner,active){active=active&&r.listing_status!=='closed'&&new Date(r.pickup_end)>new Date();const sent=new Set((r.guidance||[]).filter(g=>g.sender_role===(owner?'owner':'customer')).map(g=>g.code));return '<details class="guided-contact"><summary>Messaggi sul ritiro</summary><p class="small">Sono messaggi predefiniti, non una chat. Puoi inviare ciascun messaggio una sola volta per prenotazione. Non modificano la prenotazione e non prolungano l’orario di ritiro. Gli avvisi arrivano nell’app; la risposta non è immediata né garantita.</p>'+((r.guidance||[]).map(g=>'<p class="guided-message"><b>'+(g.sender_role==='owner'?'Chi pubblica':'Chi ritira')+'</b> · '+esc(when(g.created_at))+'<br>'+esc(g.message)+'</p>').join('')||'<p class="small">Nessun messaggio sul ritiro.</p>')+(active?'<div class="guided-actions">'+Object.entries(guidanceOptions[owner?'owner':'customer']).map(([code,label])=>'<button class="ghost" type="button" data-guidance="'+code+'" data-reservation="'+esc(r.id)+'" '+(sent.has(code)?'disabled':'')+'>'+esc(label)+(sent.has(code)?' · inviato':'')+'</button>').join('')+'</div>':'<p class="small">Ritiro concluso: puoi consultare i messaggi precedenti.</p>')+'</details>';}
function bindGuidanceActions(){document.querySelectorAll('[data-guidance]').forEach(b=>b.onclick=()=>run(b,async()=>{await rpc('saveat_send_guidance',{p_reservation_id:b.dataset.reservation,p_code:b.dataset.guidance});await loadMine();await refreshNotifications();notice('Messaggio inviato negli avvisi Saveat. La fascia di ritiro resta invariata.');}));}
function receivedNotification(kind){return ['customer_cancelled','reservation_received','reservation_changed'].includes(kind)||kind.startsWith('guide_customer_');}
let reportRows=[],reportGeneration=0,reportPeriod=null;
function reportDay(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function prepareReport(){if(!$('report-from').value){const today=reportDay();$('report-from').value=today.slice(0,8)+'01';$('report-to').value=today;}}
function visibleReportRows(){return reportRows.filter(r=>$('report-role').value==='all'||r.role===$('report-role').value);}
function reportCsvCell(value){let text=String(value??'');if(/^[\s]*[=+@-]/.test(text)||/^[\t\r\n]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"';}
function reportCsv(rows){const titles=['Data completamento (Europe/Rome)','Data storica indicativa','Ruolo','Prenotazione','Annuncio','Alimento','Quantità','Unità','Prezzo unitario EUR','Valore concordato EUR','Kg indicativi','Fonte peso'];const values=rows.map(r=>[when(r.completed_at),r.completion_time_estimated?'Sì':'No',r.role==='owner'?'Condiviso':'Ritirato',r.reservation_id,r.title,r.name,String(r.quantity).replace('.',','),r.unit,String(r.price).replace('.',','),String(r.total).replace('.',','),String(r.saved_kg).replace('.',','),r.weight_source]);return '\uFEFF'+[titles,...values].map(row=>row.map(reportCsvCell).join(';')).join('\r\n');}
function renderReport(){const rows=visibleReportRows(),count=new Set(rows.map(r=>r.reservation_id)).size,kg=rows.reduce((s,r)=>s+Number(r.saved_kg),0),value=rows.reduce((s,r)=>s+Number(r.total),0),donations=new Set(rows.filter(r=>Number(r.price)===0).map(r=>r.reservation_id)).size;const fmt=v=>new Intl.NumberFormat('it-IT',{maximumFractionDigits:2}).format(v);$('report-result').innerHTML='<div class="card padded"><p><b>'+count+(count===1?' ritiro completato':' ritiri completati')+'</b> · circa '+fmt(kg)+' kg</p><p>Valore concordato al ritiro: '+money(value)+'</p><p class="small">'+donations+(donations===1?' ritiro con alimenti donati.':' ritiri con alimenti donati.')+' Il valore somma i prezzi concordati nelle prenotazioni: non verifica gli incassi né rappresenta un documento fiscale. I kg includono pesi dichiarati e stime.</p><p class="small">Periodo: '+esc(reportPeriod?.from)+' – '+esc(reportPeriod?.to)+' · orario italiano. Le date storiche ricostruite sono indicate nel file esportato.</p>'+(rows.length?'<p class="small">Il CSV include tutti gli alimenti del periodo selezionato. Non include telefoni, indirizzi o nominativi dei clienti.</p>':'<p>Nessun ritiro completato nel periodo selezionato.</p>')+'</div>';$('export-report').disabled=!rows.length;}
async function loadReport(){if(!requireAccount())return;const uid=session.user.id,gen=++reportGeneration;const from=$('report-from').value,to=$('report-to').value;if(!from||!to||to<from)throw new Error('Controlla le date del resoconto.');$('report-result').textContent='Preparo il resoconto…';$('export-report').disabled=true;reportRows=[];try{const rows=await rpc('saveat_my_report',{p_from:from,p_to:to});if(gen!==reportGeneration||session?.user.id!==uid)return;reportRows=rows;reportPeriod={from,to};renderReport();}catch(e){if(gen===reportGeneration)$('report-result').textContent='Resoconto non disponibile. Riprova.';throw e;}}
function resetReport(){reportGeneration++;reportRows=[];reportPeriod=null;$('report-result').replaceChildren();$('export-report').disabled=true;}

const config=window.SAVEAT_CONFIG||{};
let notificationSequence=0;
async function refreshNotifications(){const seq=++notificationSequence,uid=session?.user.id;$('notifications-button').hidden=!uid;if(!uid){$('notification-alert').hidden=true;$('notifications-list').innerHTML='';notificationFingerprint=null;return;}
 const {data,error}=await db.from('saveat_notifications').select('id,kind,title,message,created_at,read_at,reservation_id').eq('user_id',uid).order('created_at',{ascending:false}).limit(100);if(seq!==notificationSequence||session?.user.id!==uid)return;if(error){$('notifications-list').textContent='Impossibile aggiornare gli avvisi. Riprova.';return;}
 const fingerprint=uid+':'+data.map(n=>n.id+':'+n.created_at+':'+(n.read_at||'')).join('|'),changed=notificationFingerprint!==null&&notificationFingerprint!==fingerprint;notificationFingerprint=fingerprint;$('notification-alert').hidden=true;const unread=data.filter(n=>!n.read_at);$('notifications-button').textContent='🔔 Avvisi'+(unread.length?' ('+unread.length+')':'');$('notifications-button').setAttribute('aria-label','Avvisi, '+unread.length+(unread.length===1?' non letto':' non letti'));if(unread.length){$('notification-alert').hidden=false;$('notification-alert').innerHTML='<b>Aggiornamenti sulle tue prenotazioni.</b> Hai '+unread.length+(unread.length===1?' avviso da leggere.':' avvisi da leggere.')+' <a href="#avvisi">Leggi gli avvisi</a>';}
 const notificationCard=n=>'<article class="card padded notification-card '+(!n.read_at?'notification-unread':'notification-read')+'"><div class="notification-card-header"><span class="notification-status">'+(n.read_at?'<span aria-hidden="true">✓</span> Già letto':'<span class="notification-dot" aria-hidden="true"></span> Da leggere')+'</span><time class="small" datetime="'+esc(n.created_at)+'">'+esc(when(n.created_at))+'</time></div><h3>'+esc(n.title)+'</h3><p class="notification-message">'+esc(n.message)+'</p><div class="notification-actions"><a class="btn ghost" href="#miei" data-my-bookings data-booking-tab="'+(receivedNotification(n.kind)?'received':'reservations')+'">'+(receivedNotification(n.kind)?'Consegne dei miei annunci':'I miei ritiri')+'</a>'+(!n.read_at?'<button class="primary" data-read="'+esc(n.id)+'" aria-label="Segna come letto: '+esc(n.title)+'">Segna come letto</button>':'<span class="notification-read-note">Avviso già letto</span>')+'</div></article>';
 const read=data.filter(n=>n.read_at),group=(id,title,rows)=>'<section class="notification-group" aria-labelledby="'+id+'"><h2 id="'+id+'">'+title+' <span class="count">'+rows.length+'</span></h2>'+rows.map(notificationCard).join('')+'</section>';
 $('notifications-list').innerHTML=data.length?'<p class="notification-summary" role="status">'+(unread.length?unread.length+(unread.length===1?' avviso da leggere.':' avvisi da leggere.'):'Tutti gli avvisi mostrati sono stati letti.')+'</p>'+(unread.length?group('notifications-unread-heading','Da leggere',unread):'')+(read.length?group('notifications-read-heading','Già letti',read):''):'<p class="empty">Nessun avviso.</p>';
 bindBookingLinks();if(changed&&location.hash==='#miei')await loadMine();
 document.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>run(b,async()=>{await rpc('saveat_read_notification',{p_id:b.dataset.read});await refreshNotifications();}));}
function bindBookingLinks(){document.querySelectorAll('[data-my-bookings]').forEach(a=>a.onclick=e=>{e.preventDefault();reservationFilter=null;myTab=a.dataset.bookingTab||'reservations';if(location.hash==='#miei')run(a,loadMine);else location.hash='miei';});}
$('notifications-button').onclick=()=>{location.hash='avvisi';};
setInterval(()=>{if(session&&document.visibilityState==='visible')refreshNotifications().catch(()=>{});},30000);
window.addEventListener('focus',()=>{if(session)run(null,async()=>{await refreshNotifications();if(location.hash==='#miei')await loadMine();});});
function notice(text,error=false){$('message').textContent=text;$('message').hidden=false;$('message').className=error?'error':'';}
function errorText(error){const t=error?.message||'Operazione non riuscita. Riprova.';if(/email not confirmed/i.test(t))return 'Email non ancora confermata. Apri il link nel messaggio più recente oppure richiedi una nuova conferma.';if(/email rate limit exceeded/i.test(t))return 'Limite temporaneo di invio email raggiunto. Attendi prima di richiedere un altro messaggio.';if(/invalid login credentials/i.test(t))return 'Email o password non corrette.';if(/permission denied|violates .*constraint|invalid input syntax|schema cache|PGRST|JWT|Libreria Supabase|relation .*does not exist|function .*does not exist/i.test(t))return 'Operazione non disponibile in questo momento. Riprova tra poco.';return /Failed to fetch|NetworkError|fetch failed/i.test(t)?'Connessione non disponibile. Controlla la rete e riprova.':t;}
async function run(button,work){if(button?.disabled)return;if(button)button.disabled=true;try{await work();}catch(e){notice(errorText(e),true);}finally{if(button)button.disabled=false;}}
async function rpc(name,args){const {data,error}=await db.rpc(name,args);if(error)throw error;return data;}
function rememberDestination(){const dest=location.hash;if(/^#(scheda\/[0-9a-f-]{36}|pubblica|miei)$/.test(dest))localStorage.setItem('saveat-return',dest);}
function isBusinessAccount(){return !!session&&profile?.account_type==='business';}
function businessExperienceView(){const business=isBusinessAccount();document.body.classList.toggle('business-account',business);$('hero-share').className='btn '+(business?'primary':'secondary');$('clear-search').hidden=!session||!profile?.home_municipality_code;document.querySelectorAll('[data-discovery-only]').forEach(e=>e.hidden=business);$('business-home').hidden=!business;$('home-heading').textContent=business?'Dai valore alle tue eccedenze.':'Il cibo buono merita di essere condiviso.';$('home-intro').textContent=business?'Pubblica le eccedenze della tua attività e organizza i ritiri.':'Trova alimenti in vendita o in dono vicino a te. Condividi quelli che non consumerai.';document.querySelector('nav a[href="#cerca"]').hidden=business;document.querySelector('nav a[href="#miei"]').textContent='La mia attività';$('mine-heading').textContent='La mia attività';$('impact-summary-link').textContent=business?'I miei annunci e consegne':'I miei annunci e ritiri';$('reservations-tab').hidden=business;$('reservations-tab').textContent=business?'Ritiri precedenti':'Ritiri';$('account-role-description').textContent=business?'Come esercente puoi pubblicare eccedenze e gestire le consegne. Le prenotazioni sono riservate agli account privati.':'Come privato puoi condividere alimenti e prenotare ritiri.';$('notifications-intro').textContent=business?'Controlla qui le prenotazioni ricevute e gli aggiornamenti sulle consegne.':'Controlla qui gli aggiornamenti sui tuoi ritiri.';const customerOption=$('report-role').querySelector('option[value="customer"]');customerOption.hidden=business;if(business&&$('report-role').value==='customer')$('report-role').value='all';if(business){$('home-list').replaceChildren();$('search-list').replaceChildren();$('load-more').hidden=true;}}

function continueAfterAuth(){localStorage.removeItem('saveat-return');location.hash='#home';}
function requireAccount(){if(!session){rememberDestination();location.hash='account';notice('Accedi oppure registrati per continuare. Dopo l’accesso arriverai alla Home.');return false;}if(!profile?.account_type){rememberDestination();location.hash='account';notice('Completa il profilo per continuare.');return false;}return true;}
async function refreshProfile(){const n=++profileRefreshSequence,uid=session?.user.id;profile=null;if(uid){const {data,error}=await db.from('saveat_profiles').select('*').eq('id',uid).single();if(n!==profileRefreshSequence||session?.user.id!==uid)return;if(error)throw error;profile=data;const meta=session.user.user_metadata||{};if(!profile.account_type&&meta.saveat_first&&meta.saveat_last&&['private','business'].includes(meta.saveat_type)){if(meta.saveat_city){await rpc(meta.saveat_activity?'saveat_save_profile_activity':'saveat_save_profile',{...(meta.saveat_activity?{p_activity:meta.saveat_activity}:{}),p_name:(meta.saveat_first+' '+meta.saveat_last).trim(),p_type:meta.saveat_type,p_business:meta.saveat_business||'',p_city:meta.saveat_city,p_radius:Number(meta.saveat_radius)||20,p_vat:meta.saveat_vat||'',p_address:meta.saveat_address||''});}else await rpc('saveat_set_profile',{p_name:(meta.saveat_first+' '+meta.saveat_last).trim(),p_type:meta.saveat_type,p_business:meta.saveat_business||''});const next=await db.from('saveat_profiles').select('*').eq('id',uid).single();if(n!==profileRefreshSequence||session?.user.id!==uid)return;if(next.error)throw next.error;profile=next.data;}}await restorePendingAvatar(uid);if(n!==profileRefreshSequence||session?.user.id!==uid)return;identityView();await applyProfileArea();}
function accountView(){const signed=!!session;$('account-heading').textContent=signed?'Il tuo profilo':'Accedi a Saveat';$('auth-form').hidden=signed;$('profile-form').hidden=!signed;
 if(signed){$('display-name').value=profile?.display_name||'';$('account-type').value=profile?.account_type||'private';$('account-type').disabled=!!profile?.account_type;$('business-name').value=profile?.business_name||'';businessView();renderBusinessActivity('profile',true);profileLocationView();renderAvatarPicker('profile');}}
function updateZoneHelp(prefix,business){const note=$(prefix+'-zone-help');if(note)note.textContent=business?'Il comune identifica la zona della tua attività. Questo account è dedicato alla pubblicazione delle eccedenze.':'All’accesso vedrai questa zona. In viaggio potrai scegliere un’altra zona o usare la posizione attuale.';}
function businessView(){const biz=$('account-type').value==='business';updateZoneHelp('profile',biz);$('business-field').hidden=!biz;$('business-name').required=biz;$('vat-number').required=biz;$('business-address').required=biz;renderBusinessActivity('profile');}

let visibleRoute=null,routeTrail=[],returningRoute=null;
function rememberRoute(next){
 const back=returningRoute&&returningRoute.hash===next?returningRoute:routeTrail.at(-1)?.hash===next?routeTrail.pop():null;returningRoute=null;
 if(visibleRoute&&visibleRoute.hash!==next&&!back)routeTrail.push({hash:visibleRoute.hash,scroll:window.scrollY});
 visibleRoute={hash:next};return back;
}
$('back-button').onclick=()=>{const previous=routeTrail.pop()||{hash:'#home',scroll:0};returningRoute=previous;location.hash=previous.hash;};
async function loadPersonalImpact(gen=routeGeneration){
 const target=$('personal-impact'),uid=session?.user.id;
 if(!uid){target.innerHTML='<p class="empty">Accedi per vedere il cibo che hai salvato.</p><a class="btn primary" href="#account">Accedi</a>';return;}
 target.textContent='Calcolo in corso…';
 try{const reservations=await rpc('saveat_my_reservations');if(gen!==routeGeneration||session?.user.id!==uid)return;
 const completed=[...new Map(reservations.filter(r=>r.status==='collected').map(r=>[r.id,r])).values()];
 const kg=completed.reduce((total,r)=>total+r.items.reduce((sum,i)=>sum+Number(i.quantity)*Number(i.saved_unit_kg??(i.unit==='kg'||i.unit==='litri'?1:.5)),0),0);
 target.innerHTML='<div class="card padded impact-card"><p>Peso stimato degli alimenti nei ritiri completati</p><p class="impact-total">Circa '+new Intl.NumberFormat('it-IT',{maximumFractionDigits:2}).format(kg)+' kg</p><p>'+completed.length+(completed.length===1?' ritiro completato':' ritiri completati')+'</p></div>';
 }catch(e){if(gen===routeGeneration)target.textContent='Impatto temporaneamente non disponibile. Riapri questa pagina per riprovare.';}
}

async function route(){closeProfileMenu();const gen=++routeGeneration;const [raw,id]=(location.hash.slice(1)||'home').split('/');let screen=['home','cerca','pubblica','scheda','miei','account','registrati','avvisi','modifica','setup','impatto'].includes(raw)?raw:'home';
 businessExperienceView();if(isBusinessAccount()&&screen==='cerca'){location.replace('#home');notice('Come esercente puoi pubblicare eccedenze e gestire le consegne.');return;}if(!db)screen='setup';else if(['pubblica','miei','modifica'].includes(screen)&&!requireAccount())return;
 const backState=rememberRoute('#'+screen+(id&&['scheda','modifica'].includes(screen)?'/'+id:''));$('back-button').hidden=screen==='home';
 document.querySelectorAll('.screen').forEach(s=>s.hidden=s.id!==screen);document.querySelectorAll('nav a').forEach(a=>{if(a.hash==='#'+screen)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});window.scrollTo(0,0);
 try{if(screen==='account')accountView();if(screen==='home'){if(isBusinessAccount())await loadImpact(gen);else await Promise.all([loadListings('home-list',true,gen),loadImpact(gen)]);}if(screen==='cerca'&&!backState){page=0;await loadListings('search-list',false,gen);}if(screen==='impatto'){prepareReport();$('report-tools').hidden=!session;await loadPersonalImpact(gen);}if(screen==='pubblica'){prepareBusinessPublication();if(!$('item-fields').children.length){addItem();preparePublication();}await loadFoodMemory();}if(screen==='miei')await loadMine();if(screen==='avvisi')await refreshNotifications();if(screen==='scheda')await loadDetail(id);if(screen==='modifica')await loadEdit(id);if(backState&&gen===routeGeneration)window.scrollTo(0,backState.scroll);}catch(e){notice(errorText(e),true);}}
async function loadImpact(gen=routeGeneration){try{const impact=await rpc('saveat_impact');if(gen!==routeGeneration)return;const kg=Number(impact.saved_kg),pickups=Number(impact.completed_pickups);if(!Number.isFinite(kg)||!Number.isFinite(pickups))throw new Error('Totale non valido');$('impact-total').textContent='Circa '+new Intl.NumberFormat('it-IT',{maximumFractionDigits:2}).format(kg)+' kg';$('impact-pickups').textContent=pickups===1?'1 ritiro completato':new Intl.NumberFormat('it-IT').format(pickups)+' ritiri completati';}catch(error){if(gen===routeGeneration){$('impact-total').textContent='Totale temporaneamente non disponibile';$('impact-pickups').textContent='';}}}
function priceUnit(unit){return {pezzi:'pezzo',confezioni:'confezione',litri:'litro',kg:'kg'}[unit]||unit;}
function quantityUnit(unit,quantity){return Number(quantity)===1?priceUnit(unit):unit;}
function matchesSearchItem(item,filters){return Number(item.available)>0&&(!filters.category||item.category===filters.category)&&(filters.offer==='all'||(filters.offer==='free'?Number(item.price)===0:Number(item.price)>0));}
function currentSearchFilters(){return {category:$('search-category').value,offer:$('search-offer').value};}
function listingProductsPreview(items){if(items.length<2)return '';const unitNames={confezioni:'confezione',pezzi:'pezzo',litri:'litro',kg:'kg'};return '<ul class="listing-products">'+items.slice(0,3).map(i=>'<li><span class="listing-product-name">'+esc(i.name)+'</span><span class="listing-product-meta">'+esc(i.available)+' '+esc(quantityUnit(i.unit,i.available))+' · '+(Number(i.price)===0?'Gratis':money(i.price)+' / '+esc(unitNames[i.unit]||i.unit))+'</span></li>').join('')+'</ul>'+(items.length>3?'<p class="listing-more">+ altri '+(items.length-3)+((items.length-3)===1?' alimento · vedi tutto':' alimenti · vedi tutti')+'</p>':'');}
function listingCard(l,filters=null){const own=session?.user.id===l.owner_id,items=(l.saveat_items||[]).filter(i=>Number(i.available)>0),photo=items.find(i=>i.photo_path)?.photo_path,paid=items.filter(i=>Number(i.price)>0),free=items.some(i=>Number(i.price)===0),single=items.length===1;if(filters&&(filters.category||filters.offer!=='all'))items.sort((a,b)=>Number(matchesSearchItem(b,filters))-Number(matchesSearchItem(a,filters)));const automaticTitle=(l.saveat_items||[]).some(i=>i.name?.trim()===l.title?.trim()),cardTitle=automaticTitle&&items.length?(single?items[0].name:items.length+' alimenti da salvare'):l.title;const offer=free&&paid.length?'In dono e in vendita':paid.length?'In vendita':'In dono';const price=single&&paid.length?money(items[0].price)+' / '+esc(priceUnit(items[0].unit)):paid.length===0?'Gratis':paid.every(i=>i.unit===paid[0].unit)?'Da '+money(Math.min(...paid.map(i=>Number(i.price))))+' / '+esc(priceUnit(paid[0].unit)):'Prezzi nei dettagli';const availability=single?esc(items[0].available)+' '+esc(quantityUnit(items[0].unit,items[0].available))+(Number(items[0].available)===1?' disponibile':' disponibili'):items.length+' alimenti disponibili';const distance=l.distance_km!=null&&Number.isFinite(Number(l.distance_km))?' · circa '+new Intl.NumberFormat('it-IT',{maximumFractionDigits:1}).format(Number(l.distance_km))+' km':'';return '<article class="card listing-compact"><a class="listing-open" href="#scheda/'+esc(l.id)+'"><div class="listing-thumb">'+(photo?'<img loading="lazy" src="'+esc(db.storage.from('saveat-photos').getPublicUrl(photo).data.publicUrl)+'" alt="">':'<span class="listing-placeholder" aria-hidden="true">'+activityIcon('other')+'</span>')+'</div><div class="listing-essential"><div class="listing-badges"><span class="listing-offer">'+offer+'</span>'+(own?'<span class="listing-own">Il tuo annuncio</span>':'')+'</div><h3>'+esc(cardTitle)+'</h3>'+sellerProfile(l)+'<p class="listing-place">'+esc(l.saveat_municipalities?.name)+' ('+esc(l.saveat_municipalities?.province)+')'+esc(distance)+'</p><p class="listing-availability">'+availability+'</p>'+listingProductsPreview(items)+'<div class="listing-bottom"><strong>'+(free&&paid.length?'In dono e in vendita':price)+'</strong><span>'+(own?'Gestisci':'Dettagli')+' <span aria-hidden="true">›</span></span></div><p class="listing-pickup">Ritiro: '+esc(pickupWindow(l.pickup_start,l.pickup_end))+'</p></div></a></article>';}
async function loadListings(target,home,gen=routeGeneration){if(isBusinessAccount()){$(target).replaceChildren();$('load-more').hidden=true;return;}const seq=++listingsSequence,requestedPage=home?0:page,area=searchArea?{...searchArea}:null,filters=home?null:currentSearchFilters();$(target).innerHTML=requestedPage&&!home?$(target).innerHTML:'<p>Caricamento…</p>';
 if(!home){const active=[filters.category,filters.offer==='free'?'In dono':filters.offer==='paid'?'In vendita':''].filter(Boolean);$('search-filter-summary').textContent=active.length?'Filtri: '+active.join(' · ')+'. Un annuncio può includere anche altri alimenti.':'';}
 if(!area){$(target).innerHTML='<p class="empty">Scegli il tuo comune o usa la posizione attuale per vedere gli alimenti vicini. <a href="#cerca">Imposta la zona</a></p>';$('load-more').hidden=true;return;}
 const size=home?6:20,args={p_lat:area.lat,p_lon:area.lon,p_radius:area.radius,p_query:home?'':$('search').value.trim(),p_page:requestedPage,p_size:size};if(!home){args.p_category=filters.category;args.p_offer=filters.offer;}
 const data=await rpc(home?'saveat_search_nearby':'saveat_search_filtered',args);if(gen!==routeGeneration||seq!==listingsSequence)return;
 const visible=data.filter(l=>l.saveat_items.some(i=>Number(i.available)>0));await loadPublicAvatars(visible);if(gen!==routeGeneration||seq!==listingsSequence)return;const content=visible.map(l=>listingCard(l,filters)).join('');
 if(requestedPage&&!home)$(target).insertAdjacentHTML('beforeend',content);else $(target).innerHTML=content||'<p class="empty">Nessun risultato per questa ricerca. Prova un altro alimento, un comune diverso o una distanza maggiore.</p>';
 if(!home)$('load-more').hidden=data.length<size;
}
let editCity=null,editListing=null,editEnded=false,editLocked=false;
function secondaryActions(content){return content?'<details class="secondary-actions"><summary>Altre azioni</summary><div class="actions-menu">'+content+'</div></details>':'';}
function ownListingActions(l,extra=''){return secondaryActions(extra+'<a class="btn ghost" href="#modifica/'+esc(l.id)+'">Modifica annuncio</a><button type="button" class="ghost" data-close="'+esc(l.id)+'" '+(l.status==='closed'?'disabled title="Annuncio già annullato"':'')+'>Annulla annuncio</button><button type="button" class="ghost danger" data-delete="'+esc(l.id)+'">Elimina annuncio</button>');}
function pickupWindow(start,end,now=new Date()){
 const a=new Date(start),b=new Date(end);if(!Number.isFinite(a.getTime())||!Number.isFinite(b.getTime()))return 'Orario non disponibile';
 const zone='Europe/Rome',day=d=>new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).format(d),today=day(now),tomorrow=new Date(today+'T00:00:00Z');tomorrow.setUTCDate(tomorrow.getUTCDate()+1);const next=tomorrow.toISOString().slice(0,10);
 const date=d=>day(d)===today?'Oggi':day(d)===next?'Domani':new Intl.DateTimeFormat('it-IT',{timeZone:zone,day:'numeric',month:'short',year:'numeric'}).format(d),hour=d=>new Intl.DateTimeFormat('it-IT',{timeZone:zone,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(d);
 return day(a)===day(b)?date(a)+', '+hour(a)+'–'+hour(b):date(a)+', '+hour(a)+' – '+date(b)+', '+hour(b);
}
function pickupTime(start,end,label='Ritiro'){return '<div class="pickup-time"><span>'+esc(label)+'</span><strong>'+esc(pickupWindow(start,end))+'</strong></div>';}

function bindDeleteActions(){document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(!confirm('Eliminare definitivamente questo annuncio anche dal tuo storico? Non potrai recuperarlo. Le prenotazioni ancora da ritirare saranno annullate con un avviso ai clienti; i loro riepiloghi resteranno disponibili.'))return;run(b,async()=>{await rpc('saveat_delete_listing',{p_id:b.dataset.delete});current=null;reservationFilter=null;myTab='listings';if(location.hash==='#miei')await loadMine();else location.hash='miei';await refreshNotifications();notice('Annuncio eliminato definitivamente dal tuo elenco e dallo storico.');});});}
function bindCloseActions(){document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>{if(!confirm('Il cibo non è più disponibile? L’annuncio sarà annullato e chi deve ancora ritirare riceverà un avviso. Le consegne dei ritiri già segnalati resteranno da confermare.'))return;run(b,async()=>{await rpc('saveat_close_listing',{p_id:b.dataset.close});if(location.hash.startsWith('#scheda/'))await loadDetail(b.dataset.close);else await loadMine();await refreshNotifications();notice('Annuncio annullato. Avvisi registrati per chi doveva ancora ritirare.');});});}
const localDateTime=v=>{const d=new Date(v);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
