async function openReservationEditor(id){if(isBusinessAccount())throw Error('Le prenotazioni sono riservate agli account privati.');const generation=++reservationEditorGeneration,uid=session?.user.id,ctx=await rpc('saveat_reservation_edit_context',{p_id:id});if(session?.user.id!==uid||generation!==reservationEditorGeneration)return;const modal=document.createElement('dialog');modal.className='reservation-editor';modal.setAttribute('aria-labelledby','reservation-editor-heading');modal.innerHTML='<form><h2 id="reservation-editor-heading">Modifica quantità del ritiro</h2><p>Le quantità indicate sono il nuovo totale da ritirare. Il prezzo unitario concordato resta invariato, anche se l’annuncio è cambiato.</p><div class="reservation-edit-items">'+ctx.items.map((i,n)=>'<div class="reservation-edit-row"><label for="reservation-quantity-'+n+'">'+esc(i.name)+' · '+esc(i.unit)+'</label><p class="small">Quantità prenotata: '+esc(i.quantity)+' · massimo prenotabile ora: '+esc(i.maximum)+' · '+money(i.price)+' / '+esc(priceUnit(i.unit))+'</p><input id="reservation-quantity-'+n+'" type="number" inputmode="decimal" min="0" max="'+esc(i.maximum)+'" step="'+(['pezzi','confezioni'].includes(i.unit)?'1':'0.1')+'" value="'+esc(i.quantity)+'" required></div>').join('')+'</div><p class="small">Chi pubblica riceverà un avviso della modifica. Puoi mettere 0 per togliere un alimento. Per annullare tutto usa Altre azioni → Annulla prenotazione. La disponibilità verrà ricontrollata alla conferma.</p><p id="reservation-edit-total" aria-live="polite"></p><p id="reservation-edit-error" role="alert"></p><button type="submit" class="primary">Salva nuove quantità</button><button type="button" class="ghost" data-dismiss>Indietro</button></form>';document.body.append(modal);const inputs=[...modal.querySelectorAll('input')],form=modal.querySelector('form'),error=modal.querySelector('[role="alert"]');let pending=null,busy=false;const total=()=>modal.querySelector('#reservation-edit-total').textContent='Nuovo totale: '+money(ctx.items.reduce((s,i,n)=>s+Number(inputs[n].value||0)*Number(i.price),0));inputs.forEach(i=>i.oninput=total);total();const close=()=>{if(!busy)modal.close();};modal.querySelector('[data-dismiss]').onclick=close;modal.oncancel=e=>{if(busy)e.preventDefault();};modal.onclose=()=>modal.remove();form.onsubmit=async e=>{e.preventDefault();if(busy||!form.reportValidity())return;if(session?.user.id!==uid){modal.close();return;}const items=ctx.items.map((i,n)=>({snapshot_id:i.snapshot_id,quantity:Number(inputs[n].value)}));if(!items.some(i=>i.quantity>0)){error.textContent='Per togliere tutti gli alimenti usa Altre azioni → Annulla prenotazione.';return;}if(items.every((i,n)=>i.quantity===Number(ctx.items[n].quantity))){error.textContent='Non hai modificato le quantità.';return;}const signature=JSON.stringify(items);if(!pending||pending.signature!==signature)pending={signature,id:crypto.randomUUID()};busy=true;for(const c of form.elements)c.disabled=true;error.textContent='';let saved=false;try{await rpc('saveat_change_reservation',{p_id:id,p_items:items,p_revision:ctx.revision,p_request_id:pending.id});saved=true;modal.close();await loadMine();notice('Quantità aggiornate. Chi pubblica è stato avvisato.');}catch(e){if(saved)notice('Modifica salvata. Riapri La mia attività → Ritiri per aggiornare il riepilogo.');else error.textContent=errorText(e);}finally{busy=false;for(const c of form.elements)c.disabled=false;}};modal.showModal();}

