function cityPicker(prefix,onPick){const input=$(prefix+'-city'),box=$(prefix+'-city-options');let timer,sequence=0;input.addEventListener('input',()=>{onPick(null);clearTimeout(timer);const n=++sequence;const text=input.value.trim();box.hidden=true;input.setAttribute('aria-expanded','false');if(text.length<2||!db)return;timer=setTimeout(async()=>{try{const {data,error}=await db.from('saveat_municipalities').select('code,name,province,latitude,longitude').ilike('name',text.replace(/[%,_]/g,'')+'%').order('name').limit(12);if(error)throw error;if(n!==sequence)return;box.replaceChildren();data.forEach(c=>{const b=document.createElement('button');b.type='button';b.role='option';b.textContent=c.name+' ('+c.province+')';b.onclick=()=>{onPick(c);input.value=b.textContent;box.hidden=true;input.setAttribute('aria-expanded','false');input.focus();};box.append(b);});box.hidden=!data.length;input.setAttribute('aria-expanded',String(!!data.length));}catch(e){notice(errorText(e),true);}},180);});input.addEventListener('keydown',e=>{if(e.key==='ArrowDown'&&!box.hidden){e.preventDefault();box.querySelector('button')?.focus();}if(e.key==='Escape'){box.hidden=true;input.setAttribute('aria-expanded','false');}});box.addEventListener('keydown',e=>{const buttons=[...box.querySelectorAll('button')],index=buttons.indexOf(document.activeElement);if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();buttons[(index+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus();}if(e.key==='Escape'){box.hidden=true;input.setAttribute('aria-expanded','false');input.focus();}});document.addEventListener('click',e=>{if(!input.parentElement.contains(e.target)){box.hidden=true;input.setAttribute('aria-expanded','false');}});}
function safeConfig(url,key){const u=new URL(url);if(u.protocol!=='https:'||!u.hostname.endsWith('.supabase.co')||u.username||u.password||u.pathname!=='/')throw new Error('Usa il Project URL https://…supabase.co del progetto.');if(key.startsWith('sb_secret_'))throw new Error('Questa è una chiave segreta. Usa la publishable key.');if(!key.startsWith('sb_publishable_')){try{const payload=JSON.parse(atob(key.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));if(payload.role!=='anon')throw Error();}catch{throw new Error('Usa una publishable key o la chiave anon pubblica.');}}return {url:u.origin,key};}
