$('signup-type').onchange=()=>{const biz=$('signup-type').value==='business';updateZoneHelp('signup',biz);$('signup-business-field').hidden=!biz;$('signup-business').required=biz;$('signup-vat').required=biz;$('signup-address').required=biz;renderAvatarPicker('signup');renderBusinessActivity('signup');$('signup-role-description').textContent=biz?'Come esercente puoi pubblicare eccedenze e gestire le consegne ai privati. Non puoi prenotare ritiri.':'Come privato puoi pubblicare alimenti e prenotare ritiri. Puoi donare o vendere, con pagamento al ritiro.';};
$('signup-form').onsubmit=e=>{e.preventDefault();run(e.submitter,async()=>{if($('signup-password').value!==$('signup-repeat').value)throw new Error('Le due password non coincidono.');const first=$('signup-first').value.trim(),last=$('signup-last').value.trim();if(!first||!last)throw new Error('Inserisci nome e cognome.');if(avatarState('signup').pending)throw new Error('Attendi che l’immagine sia pronta.');const signupPhoto=avatarState('signup').file;const activity=selectedActivity('signup'),prefs=profileArgs('signup');const email=$('signup-email').value.trim();const {data,error}=await db.auth.signUp({email,password:$('signup-password').value,options:{emailRedirectTo:location.origin+location.pathname,data:{saveat_first:first,saveat_last:last,saveat_type:$('signup-type').value,saveat_activity:activity,saveat_business:$('signup-business').value.trim(),saveat_city:prefs.p_city,saveat_radius:prefs.p_radius,saveat_vat:prefs.p_vat,saveat_address:prefs.p_address,saveat_return:localStorage.getItem('saveat-return')||''}}});if(error)throw error;let signupPhotoWarning='';if(signupPhoto&&data.user?.id){try{await avatarPendingStore('put',data.user.id,signupPhoto);}catch{signupPhotoWarning=' La foto non è stata conservata: selezionala dal profilo dopo l’accesso.';}}else if(signupPhoto)signupPhotoWarning=' Seleziona la foto dal profilo dopo l’accesso.';clearAvatarState('signup');renderAvatarPicker('signup');$('email').value=email;$('signup-password').value='';$('signup-repeat').value='';if(data.session){session=data.session;await refreshProfile();await refreshNotifications();continueAfterAuth();notice('Account creato.'+(signupPhoto&&!profile?.avatar_path?' La foto non è ancora caricata: puoi riprovare dal profilo.':''));}else{$('signup-sent').hidden=false;$('resend-confirmation').hidden=false;notice('Controlla la tua email. Dopo la conferma potrai accedere alla Home.'+signupPhotoWarning);}});};
$('resend-confirmation').onclick=()=>run($('resend-confirmation'),async()=>{if(!$('email').value||!$('email').checkValidity())throw new Error('Inserisci la tua email nel campo Email.');const {error}=await db.auth.resend({type:'signup',email:$('email').value.trim(),options:{emailRedirectTo:location.origin+location.pathname}});if(error)throw error;notice('Conferma richiesta. Controlla il messaggio più recente nella tua posta.');});
$('forgot').onclick=()=>run($('forgot'),async()=>{if(!$('email').checkValidity()||!$('email').value)throw new Error('Inserisci la tua email.');const {error}=await db.auth.resetPasswordForEmail($('email').value.trim(),{redirectTo:location.origin+location.pathname+'#account'});if(error)throw error;notice('Se esiste un account, riceverai un link per reimpostare la password.');});
$('reset-form').onsubmit=e=>{e.preventDefault();run(e.submitter,async()=>{const {error}=await db.auth.updateUser({password:$('new-password').value});if(error)throw error;$('reset-form').reset();$('reset-form').hidden=true;notice('Password aggiornata.');});};
$('profile-form').onsubmit=e=>{e.preventDefault();run(e.submitter,async()=>{if(avatarState('profile').pending)throw new Error('Attendi che l’immagine sia pronta.');await rpc('saveat_save_profile_activity',{...profileArgs('profile'),p_activity:selectedActivity('profile')});await saveProfileAvatar();areaAccount=undefined;await refreshProfile();accountView();notice(isBusinessAccount()?'Profilo salvato. Puoi condividere eccedenze e gestire le consegne.':'Profilo salvato. Ora puoi pubblicare e prenotare.');localStorage.removeItem('saveat-return');});};
$('logout').onclick=()=>logoutAccount($('logout'));
