(async()=>{try{const fragment=new URLSearchParams(location.hash.slice(1)),query=new URLSearchParams(location.search);const callbackError=fragment.get('error_description')||query.get('error_description');const callback=fragment.has('access_token')||query.has('code');let recovery=false;if(config.url&&config.key){const c=safeConfig(config.url,config.key);if(!window.supabase)throw new Error('Libreria Supabase non disponibile.');db=window.supabase.createClient(c.url,c.key);db.auth.onAuthStateChange((event,s)=>{const previous=session?.user.id;session=s;if(previous!==s?.user.id){reservationEditorGeneration++;document.querySelectorAll('dialog.reservation-editor').forEach(d=>d.close());closeProfileMenu();clearAvatarState('profile');publicAvatarCache.clear();foodMemory=[];foodMemoryAccount=null;foodMemorySequence++;profile=null;resetReport();profileRefreshSequence++;mineGeneration++;listingsSequence++;current=null;editListing=null;pendingRequest=null;reservationFilter=null;myTab='listings';areaAccount=undefined;$('personal-impact').innerHTML='';routeTrail=[];returningRoute=null;visibleRoute=null;$('my-content').innerHTML='';$('detail').innerHTML='';$('notifications-list').innerHTML='';notificationSequence++;notificationFingerprint=null;$('edit-form').hidden=true;$('publish-form').reset();clearPhotoPreviews($('item-fields'));$('item-fields').replaceChildren();publishCity=null;}if(event==='PASSWORD_RECOVERY'){recovery=true;$('reset-form').hidden=false;location.hash='account';}identityView();$('notification-alert').hidden=true;$('notifications-button').hidden=!session;if(['SIGNED_IN','SIGNED_OUT','TOKEN_REFRESHED','USER_UPDATED'].includes(event))setTimeout(()=>run(null,async()=>{await refreshProfile();await refreshNotifications();if(!recovery){if(event==='SIGNED_IN'&&previous!==s?.user.id&&location.hash==='#account')continueAfterAuth();await route();}}),0);});const {data,error}=await db.auth.getSession();if(error)throw error;session=data.session;await refreshProfile();await refreshNotifications();if(session&&!recovery&&(callback||location.hash==='#account'))continueAfterAuth();if(callback&&session&&!recovery){notice('Email confermata. Sei collegato a Saveat.');}if(callbackError){location.hash='account';$('resend-confirmation').hidden=false;notice(/expired|invalid/i.test(callbackError)?'Il link di conferma è scaduto o non valido. Inserisci la tua email e richiedi una nuova conferma.':'La conferma email non è riuscita. Richiedi un nuovo messaggio e apri il link più recente.',true);}}await route();}catch(e){notice(errorText(e),true);}})();
